def build_context(passages, max_chars=6000):
    """Assemble retrieved passages while retaining source labels."""
    blocks = []
    used = 0
    for passage in passages:
        block = f"[Source: {passage['source']}]\n{passage['text']}"
        if used + len(block) > max_chars:
            break
        blocks.append(block)
        used += len(block)
    return "\n\n---\n\n".join(blocks)

