def get_user(user_id, cache, repository):
    key = f"user:{user_id}"
    cached = cache.get(key)
    if cached is not None:
        return cached

    user = repository.fetch_user(user_id)
    if user is not None:
        cache.set(key, user, ttl=300)
    return user

